import test from 'node:test';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';import {readFileSync,existsSync} from 'node:fs';import {games,released,getGame,gameForPath,cacheName,shellName} from '../site/catalog.js';
const read=p=>readFileSync(new URL('../site/'+p,import.meta.url),'utf8');
test('seven approved games; future titles have no launch entry',()=>{assert.deepEqual(released.map(g=>g.id),["legacy","cubiq","block-nova","feather-fury","ky-vien","garden-through-time","huyen-anh"]);assert.equal(getGame('shadow-blade'),undefined);assert.equal(getGame('mmorpg'),undefined);assert.equal(new Set(games.map(g=>g.id)).size,games.length)});
test('all declared resources exist and game paths are isolated',()=>{for(const g of released){assert(g.files.includes(g.entry));for(const p of g.files){assert(p.startsWith('games/'+g.id+'/'));assert(existsSync(new URL('../site/'+p,import.meta.url)));assert.equal(gameForPath(p),g)}}assert.equal(gameForPath('index.html'),undefined)});
test('PWA identity and original save key preserved',()=>{const m=JSON.parse(read('manifest.webmanifest'));assert.equal(m.id,'./');assert.equal(m.scope,'./');assert.equal(m.start_url,'./');assert.match(read('games/legacy/src/save.js'),/KEY='thien-thu-v8'/);assert(!read('games/legacy/index.html').includes('rel="manifest"'));assert.match(read('games/legacy/src/app.js'),/hubBtn.*persist\(\)/)});
test('scope-specific cache identities, classic update path, no forced takeover',()=>{let a='https://a.test/thien_thu/',b='https://a.test/other/';assert.notEqual(cacheName(a,released[0]),cacheName(b,released[0]));assert.notEqual(shellName(a),cacheName(a,released[0]));const sw=read('sw.js');assert.match(sw,/importScripts/);assert(!sw.includes('skipWaiting'));assert.match(sw,/thien-thu:\$\{scope\}/)});
test('all shell resources exist',()=>{for(const m of read('sw.js').match(/const shellFiles=\[(.*?)\];/s)[1].matchAll(/'([^']+)'/g))assert(existsSync(new URL('../site/'+m[1],import.meta.url)),m[1])});

test('all catalog resource digests match shipped files',()=>{for(const g of released){assert.equal(Object.keys(g.integrity).length,g.files.length);for(const p of g.files)assert.equal(g.integrity[p],createHash('sha256').update(readFileSync(new URL('../site/'+p,import.meta.url))).digest('hex'))}});

test('released covers are automatically included in shell cache',()=>{assert.match(read('sw.js'),/for\(const g of released\)if\(!shellFiles.includes\(g.cover\)\)shellFiles.push\(g.cover\)/)});
